return {
  nodes: [{ id: "n_start", kind: "start", x: 80, y: 160, config: {} }],
  edges: [],
  variables: [],
  start: "n_start",
};

const nodes = [];
const edges = [];
const source = definition?.nodes || {};

// Link fields, in the order the engine reads them.
const SINGLE = ["next", "body", "on_error", "on_approve", "on_reject",
                "on_timeout", "on_unsupported", "else", "default"];

let column = 0;
for (const [id, node] of Object.entries(source)) {
  const layout = node.editor || {};
  nodes.push({
    id,
    kind: node.kind,
    x: layout.x ?? 80 + (column % 5) * 260,
    y: layout.y ?? 100 + Math.floor(column / 5) * 170,
    label: node.label,
    command: node.command,
    action: node.action,
    playbook: node.playbook,
    config: node.inputs || {},
    output_var: node.output_var,
    retry: node.retry,
    timeout_ms: node.timeout_ms,
    compensation: node.compensation,
    settings: pickSettings(node),
  });
  column += 1;

  for (const port of SINGLE) {
    if (typeof node[port] === "string") {
      edges.push({ id: `e_${id}_${port}`, from: id, port, to: node[port] });
    }
  }
  for (const branch of node.branches || []) {
    edges.push({ id: `e_${id}_branch_${branch}`, from: id, port: "branches",
                 to: branch });
  }
  for (const clause of node.when || []) {
    edges.push({ id: `e_${id}_when_${clause.then}`, from: id, port: "then",
                 to: clause.then, label: clause.if });
  }
  for (const [value, target] of Object.entries(node.cases || {})) {
    edges.push({ id: `e_${id}_case_${value}`, from: id, port: "case",
                 to: target, label: value });
  }
}

return {
  nodes,
  edges: edges.filter((edge) => source[edge.to] !== undefined),
  variables: definition?.variables || [],
  start: definition?.start || nodes[0]?.id,
};

const LINKS = new Set(["kind", "next", "body", "on_error", "on_approve",
  "on_reject", "on_timeout", "on_unsupported", "else", "default", "branches",
  "when", "cases", "inputs", "editor", "command", "action", "playbook",
  "output_var", "retry", "timeout_ms", "compensation", "label"]);
const settings = {};
for (const [key, value] of Object.entries(node)) {
  if (!LINKS.has(key)) settings[key] = value;
}
return settings;

const nodes = {};

for (const node of model.nodes) {
  const out = { kind: node.kind, editor: { x: Math.round(node.x), y: Math.round(node.y) } };
  if (node.label) out.label = node.label;
  if (node.command) out.command = node.command;
  if (node.action) out.action = node.action;
  if (node.playbook) out.playbook = node.playbook;
  if (node.output_var) out.output_var = node.output_var;
  if (node.retry) out.retry = node.retry;
  if (node.timeout_ms) out.timeout_ms = node.timeout_ms;
  if (node.compensation) out.compensation = node.compensation;
  if (node.config && Object.keys(node.config).length) out.inputs = node.config;
  Object.assign(out, node.settings || {});
  nodes[node.id] = out;
}

for (const edge of model.edges) {
  const node = nodes[edge.from];
  if (!node) continue;
  if (edge.port === "branches") {
    (node.branches ||= []).push(edge.to);
  } else if (edge.port === "case") {
    (node.cases ||= {})[edge.label ?? edge.to] = edge.to;
  } else if (edge.port === "then" && node.kind === "condition") {
    (node.when ||= []).push({ if: edge.label || "true", then: edge.to });
  } else {
    node[edge.port] = edge.to;
  }
}

return { start: model.start, variables: model.variables || [], nodes };

const problems = [];
const byId = new Map(model.nodes.map((n) => [n.id, n]));
const kinds = new Map();
for (const entry of palette.core || []) kinds.set(entry.kind, entry);

// 1. Exactly one start, and it exists.
const starts = model.nodes.filter((n) => n.kind === "start");
if (starts.length !== 1) {
  problems.push({ severity: "error", node: starts[1]?.id,
                  message: `a playbook needs exactly one Start node, found ${starts.length}` });
}

// 2. Reachability from start.
const seen = new Set();
const frontier = [model.start];
while (frontier.length) {
  const current = frontier.pop();
  if (!current || seen.has(current) || !byId.has(current)) continue;
  seen.add(current);
  for (const edge of model.edges) {
    if (edge.from === current) frontier.push(edge.to);
  }
}
for (const node of model.nodes) {
  if (!seen.has(node.id)) {
    problems.push({ severity: "error", node: node.id,
                    message: "unreachable from Start" });
  }
}

// 3. Dangling edges.
for (const edge of model.edges) {
  if (!byId.has(edge.to)) {
    problems.push({ severity: "error", node: edge.from,
                    message: `${edge.port} points at a node that no longer exists` });
  }
}

// 4. Required config, per node kind and per command schema.
for (const node of model.nodes) {
  const schema = schemaFor(node, palette);
  for (const required of schema?.required || []) {
    const value = node.config?.[required];
    if (value === undefined || value === "" || value === null) {
      problems.push({ severity: "error", node: node.id,
                      message: `${required} is required` });
    }
  }
}

// 5. Bounded loops.
for (const node of model.nodes) {
  if (node.kind !== "for_each" && node.kind !== "while") continue;
  const limit = Number(node.config?.max_iterations);
  if (!Number.isInteger(limit) || limit < 1 || limit > 10000) {
    problems.push({ severity: "error", node: node.id,
                    message: "max_iterations must be between 1 and 10000" });
  }
}

// 6. A high-risk approval cannot proceed on timeout.
for (const node of model.nodes) {
  if (node.kind !== "approval") continue;
  if (node.config?.risk_level === "high" &&
      node.config?.on_timeout_behaviour === "proceed") {
    problems.push({ severity: "error", node: node.id,
                    message: "a high-risk approval cannot proceed on timeout" });
  }
  if (!model.edges.some((e) => e.from === node.id && e.port === "on_approve")) {
    problems.push({ severity: "error", node: node.id,
                    message: "nothing is wired to on_approve" });
  }
}

// 7. Mutating steps with no error branch, and response nodes whose EDR
//    coverage is partial. Warnings: they are judgement calls, not mistakes.
for (const node of model.nodes) {
  const entry = paletteEntry(node, palette);
  if (entry?.effect === "mutating" &&
      !model.edges.some((e) => e.from === node.id && e.port === "on_error")) {
    problems.push({ severity: "warning", node: node.id,
                    message: "a step that changes the estate has no on_error branch" });
  }
  if (node.kind === "response") {
    const coverage = entry?.coverage;
    const wired = model.edges.some((e) => e.from === node.id &&
                                          e.port === "on_unsupported");
    if (coverage && coverage.percent < 99 && !wired) {
      problems.push({ severity: "warning", node: node.id,
        message: `${node.action} covers ${coverage.percent}% of hosts and ` +
                 `on_unsupported is not wired - those hosts will fail the step` });
    }
    for (const spot of coverage?.blind_spots || []) {
      problems.push({ severity: "info", node: node.id,
        message: `${spot.integration}: ${spot.reason}` });
    }
  }
  if (entry && entry.available === false) {
    problems.push({ severity: "error", node: node.id,
                    message: entry.unavailable_reason });
  }
}

return problems;

if (node.kind === "command") {
  for (const entries of Object.values(palette.commands || {})) {
    const found = entries.find((e) => e.command === node.command);
    if (found) return found;
  }
  return null;
}
if (node.kind === "response") {
  return (palette.response_actions || []).find((e) => e.action === node.action);
}
return (palette.core || []).find((e) => e.kind === node.kind);

const entry = paletteEntry(node, palette);
if (!entry) return null;
const schema = entry.config_schema;
if (!schema) return null;
if (schema.type === "object") return schema;
// Core nodes declare a bare property map; normalise it to a schema.
return { type: "object", properties: schema, required: [] };

const past = [];
const future = [];
const LIMIT = 100;

return {
  push(model, label) {
    past.push({ model: structuredClone(model), label });
    if (past.length > LIMIT) past.shift();
    future.length = 0;
  },
  undo(current) {
    const entry = past.pop();
    if (!entry) return null;
    future.push({ model: structuredClone(current), label: entry.label });
    return entry;
  },
  redo(current) {
    const entry = future.pop();
    if (!entry) return null;
    past.push({ model: structuredClone(current), label: entry.label });
    return entry;
  },
  get undoLabel() { return past[past.length - 1]?.label ?? null; },
  get redoLabel() { return future[future.length - 1]?.label ?? null; },
};

globalThis.SOAR = globalThis.SOAR || {};
Object.assign(globalThis.SOAR, {
  emptyModel,
  fromDefinition,
  toDefinition,
  localValidate,
  paletteEntry,
  schemaFor,
  createHistory,
  newNodeId,
});
